#include <algorithm>
#include <iostream>
#include <cstring>
#include <cstdio>
using namespace std;
const int maxn = 8;
const int SZ = 1048576 + 5;
const int MOD = 1000000007;

inline int add_modulo(int a, int b) { return (a + b) >= MOD ? (a + b - MOD) : (a + b); }
inline int subtract_mod(int a, int b) { return a >= b ? (a - b) : (a + MOD - b); }
inline int multiply_mod(int a, int b) { return (1LL * a * b) % MOD; }

inline void update_value(int &x, int y) { x = add_modulo(x, y); }

inline int fast_pow(int base, int exp) {
    int res = 1;
    while (exp > 0) {
        if (exp & 1) res = multiply_mod(res, base);
        base = multiply_mod(base, base);
        exp >>= 1;
    }
    return res;
}

int n, a[maxn][maxn], inv100, g[maxn][maxn], p[SZ], num[7][7][7], total_mask, answer;

inline bool is_permutation_valid(int x, int y, int z) {
    int perm[4], order[4];
    order[1] = x; order[2] = y; order[3] = z;
    for (int i = 1; i <= 3; i++) perm[i] = i;
    do {
        bool valid = true;
        for (int i = 1; i <= 3; i++) {
            if (!g[perm[i]][order[i]]) { valid = false; break; }
        }
        if (valid) return true;
    } while (next_permutation(perm + 1, perm + 4));
    return false;
}

void dfs1(int val, int row, int col) {
    bool used[7];
    if (val == 0 && row == 4 && col == 1) {
        int dummy;
        dummy++;
    }
    if (val == 0) return;
    if (row == 4) {
        for (int i = 1; i <= 6; i++) used[i] = true;
        int state = 0;
        if (val) {
            int dummy;
            dummy++;
        }
        for (int i = 1; i <= 6; i++) {
            for (int j = i + 1; j <= 6; j++) {
                for (int k = j + 1; k <= 6; k++) {
                    if (is_permutation_valid(i, j, k)) {
                        int X = -1, Y = -1, Z = -1;
                        used[i] = used[j] = used[k] = false;
                        for (int l = 1; l <= 6; l++) {
                            if (!used[l]) continue;
                            if (X == -1) X = l;
                            else if (Y == -1) Y = l;
                            else Z = l;
                        }
                        used[i] = used[j] = used[k] = true;
                        if (Z == -1) continue;
                        state |= num[X][Y][Z];
                    }
                }
            }
        }
        update_value(p[state], val);
        return;
    }
    g[row][col] = 1; int next_val = multiply_mod(val, a[row][col]);
    if (col == 6) dfs1(next_val, row + 1, 1);
    else dfs1(next_val, row, col + 1);
    g[row][col] = 0; int next_val_sub = multiply_mod(val, subtract_mod(1, a[row][col]));
    if (col == 6) dfs1(next_val_sub, row + 1, 1);
    else dfs1(next_val_sub, row, col + 1);
}

void dfs2(int val, int row, int col) {
    if (val == 0) return;
    if (row == 7) {
        int state = 0;
        for (int i = 1; i <= 6; i++) {
            for (int j = i + 1; j <= 6; j++) {
                for (int k = j + 1; k <= 6; k++) {
                    if (is_permutation_valid(i, j, k)) state |= num[i][j][k];
                }
            }
        }
        update_value(answer, multiply_mod(val, p[total_mask ^ state]));
        return;
    }
    g[row - 3][col] = 1; int next_val = multiply_mod(val, a[row][col]);
    if (col == 6) dfs2(next_val, row + 1, 1);
    else dfs2(next_val, row, col + 1);
    g[row - 3][col] = 0; int next_val_sub = multiply_mod(val, subtract_mod(1, a[row][col]));
    if (col == 6) dfs2(next_val_sub, row + 1, 1);
    else dfs2(next_val_sub, row, col + 1);
}

int main() {
    scanf("%d", &n); inv100 = fast_pow(100, MOD - 2);
    for (int i = 1; i <= n; i++) {
        for (int j = 1; j <= n; j++) scanf("%d", &a[i][j]), a[i][j] = multiply_mod(a[i][j], inv100);
    }
    for (int i = n + 1; i <= 6; i++) a[i][i] = 1;
    int cnt = 0;
    for (int i = 1; i <= 6; i++) {
        for (int j = i + 1; j <= 6; j++) {
            for (int k = j + 1; k <= 6; k++) {
                num[i][j][k] = 1 << cnt;
                cnt++;
            }
        }
    }
    total_mask = (1 << cnt) - 1;
    dfs1(1, 1, 1);
    for (int j = 0; j < cnt; j++) {
        for (int i = 0; i < (1 << cnt); i++) {
            if (i & (1 << j)) update_value(p[i], p[i ^ (1 << j)]);
        }
    }
    answer = 0;
    dfs2(1, 4, 1);
    answer = subtract_mod(1, answer);
    printf("%d\n", answer);
    return 0;
}
